<?php $title='Join Odynasties'; require 'config/config.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']);$email=trim($_POST['email']);$phone=trim($_POST['phone']);$blood=$_POST['blood_group'] ?: null;$pw=$_POST['password']; if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<8){flash('error','Enter valid details. Password must be at least 8 characters.');}else{try{$s=$pdo->prepare('INSERT INTO users(name,email,phone,blood_group,password_hash) VALUES(?,?,?,?,?)');$s->execute([$name,$email,$phone,$blood,password_hash($pw,PASSWORD_DEFAULT)]);flash('success','Registration successful. You can now log in.');header('Location: login.php');exit;}catch(PDOException $e){flash('error','That email address is already registered.');}}} require 'includes/header.php'; ?>
<div class="formwrap"><h1>Join Odynasties</h1><p class="muted">Create your community account.</p><form method="post"><div class="field"><label>Full name</label><input name="name" required></div><div class="formgrid"><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Phone</label><input name="phone"></div></div><div class="formgrid"><div class="field"><label>Blood group</label><select name="blood_group"><option value="">Select</option><?php foreach(['O+','O-','A+','A-','B+','B-','AB+','AB-'] as $b): ?><option><?=e($b)?></option><?php endforeach; ?></select></div><div class="field"><label>Password</label><input type="password" name="password" minlength="8" required></div></div><button class="btn">Create Account</button></form></div><?php require 'includes/footer.php'; ?>
